mkdir -p /tmp/bot-check && cat > /tmp/bot-check/bot.check.mjs <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { onInbound, check } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g5-2/bot.mjs";

const H = 60 * 60 * 1000;
const T0 = new Date("2026-10-20T10:00:00Z");
const at = (ms) => new Date(T0.getTime() + ms);
let n = 0;
const uid = () => `user-${++n}`;

test("never-contacted customer: freeform blocked, template allowed", () => {
  const u = uid();
  assert.deepEqual(check(u, "freeform", at(0)), { allowed: false, rule: "no_open_service_window" });
  assert.deepEqual(check(u, "template", at(0)), { allowed: true, rule: null });
});

test("freeform window: open under 24h, closed at exactly 24h", () => {
  const u = uid();
  onInbound(u, "hi", at(0));
  assert.deepEqual(check(u, "freeform", at(H)), { allowed: true, rule: null });
  assert.deepEqual(check(u, "freeform", at(24 * H - 1)), { allowed: true, rule: null });
  assert.deepEqual(check(u, "freeform", at(24 * H)), { allowed: false, rule: "no_open_service_window" });
});

test("template allowed after window closes", () => {
  const u = uid();
  onInbound(u, "hi", at(0));
  assert.deepEqual(check(u, "template", at(72 * H)), { allowed: true, rule: null });
});

test("later customer message reopens the window; out-of-order timestamp does not shrink it", () => {
  const u = uid();
  onInbound(u, "hi", at(0));
  onInbound(u, "again", at(30 * H));
  onInbound(u, "old one arrives late", at(1 * H));
  assert.equal(check(u, "freeform", at(40 * H)).allowed, true);
});

test("stop keywords in phone-keyboard variants opt out (freeform and template blocked)", () => {
  const variants = ["STOP", "stop", " Stop. ", "STOP!!", "stop 🛑", "Stop ", "​STOP", "UNSUBSCRIBE", "stopall", "Cancel", "end", "quit", "(stop)"];
  for (const text of variants) {
    const u = uid();
    onInbound(u, "hello", at(0));
    onInbound(u, text, at(H));
    assert.deepEqual(check(u, "freeform", at(2 * H)), { allowed: false, rule: "opted_out" }, text);
    assert.deepEqual(check(u, "template", at(2 * H)), { allowed: false, rule: "opted_out" }, text);
  }
});

test("opt-out sticks across later normal messages", () => {
  const u = uid();
  onInbound(u, "STOP", at(0));
  onInbound(u, "hello?", at(H));
  assert.deepEqual(check(u, "template", at(2 * H)), { allowed: false, rule: "opted_out" });
});

test("ordinary sentences containing a keyword are not opt-outs", () => {
  const sentences = ["stop by the store tomorrow", "Can you stop my line?", "please don't stop", "I want to cancel my plan", "the end of the month", "stop stop"];
  for (const text of sentences) {
    const u = uid();
    onInbound(u, text, at(0));
    assert.deepEqual(check(u, "freeform", at(H)), { allowed: true, rule: null }, text);
  }
});

test("start keywords re-enable messaging after opt-out", () => {
  for (const text of ["START", "start!", " Unstop. "]) {
    const u = uid();
    onInbound(u, "STOP", at(0));
    assert.equal(check(u, "template", at(H)).rule, "opted_out");
    onInbound(u, text, at(2 * H));
    assert.deepEqual(check(u, "template", at(3 * H)), { allowed: true, rule: null }, text);
    assert.deepEqual(check(u, "freeform", at(3 * H)), { allowed: true, rule: null }, text);
  }
});

test("a sentence starting with start does not re-enable", () => {
  const u = uid();
  onInbound(u, "STOP", at(0));
  onInbound(u, "start the new plan please", at(H));
  assert.deepEqual(check(u, "template", at(2 * H)), { allowed: false, rule: "opted_out" });
});

test("unknown type is blocked", () => {
  const u = uid();
  onInbound(u, "hi", at(0));
  assert.deepEqual(check(u, "marketing", at(H)), { allowed: false, rule: "unknown_type" });
});

test("invalid inbound timestamp does not poison the window", () => {
  const u = uid();
  onInbound(u, "hi", new Date("nope"));
  assert.equal(check(u, "freeform", at(0)).allowed, false);
  onInbound(u, "hi again", at(0));
  assert.equal(check(u, "freeform", at(H)).allowed, true);
});

test("check does not create state for unknown users", () => {
  const u = uid();
  check(u, "freeform", at(0));
  onInbound(u, "STOP", at(0));
  assert.equal(check(u, "template", at(H)).rule, "opted_out");
});
EOF
cd /tmp/bot-check && node --test bot.check.mjs 2>&1 | tail -25
